mapper.select:
/* AppChkLst01Mapper.selectChkLstInfo */ SELECT A.CMPNY_CD AS cmpnyCd , A.CHKLST_TYPE AS chklstType , A.CHKPT_DESC AS chkptDesc , A.CHKPT_NM AS chkptNm , S.SITE_NM AS siteNm , B.INSPECT_ITEM_CD AS inspectItemCd , B.INSPECT_ITEM_SUBJ AS inspectItemSubj , 'Y' AS inspectValue , B.SORT_IDX AS sortIdx
, CASE WHEN ANS.INSPECT_ITEM_CD IS NULL THEN 'N' ELSE 'Y' END AS alreadyAnswered , IFNULL(ANS.PERFORM_USER_NM, '') AS performUserNm , IFNULL(ANS.PERFORM_USER_CD, '') AS performUserCd FROM TB_CHKPT_TYPE_MGMT A INNER JOIN TB_CHKPT_INSPECT_ITEM B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.SITE_CD = B.SITE_CD AND A.CHKLST_TYPE = B.CHKLST_TYPE ) LEFT JOIN TB_SITE S ON ( A.CMPNY_CD = S.CMPNY_CD AND A.SITE_CD = S.SITE_CD )
LEFT JOIN TB_CHKPT_INSPECT_ANSWER ANS ON ( A.CMPNY_CD = ANS.CMPNY_CD AND A.SITE_CD = ANS.SITE_CD AND A.CHKPT_CD = ANS.CHKPT_CD AND B.INSPECT_ITEM_CD = ANS.INSPECT_ITEM_CD AND ANS.WORK_DATE = DATE_FORMAT(NOW(), '%Y%m%d') ) WHERE 1=1 AND A.CMPNY_CD = #{ token.gv_cmpnyCd } AND A.SITE_CD = #{ param.siteCd } AND A.CHKPT_CD = #{ param.chkptCd } AND A.USE_YN = 'Y' AND B.USE_YN = 'Y' AND B.STR_DATE <= DATE_FORMAT(NOW(), '%Y%m%d') ORDER BY B.SORT_IDX

/* AppChkLst01Mapper.selectSiteNm */
SELECT
    SITE_NM
FROM TB_SITE
WHERE 1=1
  AND CMPNY_CD = #{ cmpnyCd }
  AND SITE_CD  = #{ siteCd }

mapper.insert:
/* AppChkLst01Mapper.mergeChkptInspectAnswer */
INSERT INTO TB_CHKPT_INSPECT_ANSWER (
    CMPNY_CD
    , SITE_CD
    , CHKPT_CD
    , INSPECT_ITEM_CD
    , WORK_DATE
    , INSPECT_ANSWER_TYPE
    , ANSWER_DESC
    , FILE_MGMT_CD
    , PERFORM_CMPNY_CD
    , PERFORM_USER_CD
    , PERFORM_USER_NM
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
VALUES(
    #{token.gv_cmpnyCd}
    , #{param.siteCd}
    , #{param.chkptCd}
    , #{param.inspectItemCd}
    , #{param.workDate}
    , #{param.inspectAnswerType}
    , #{param.answerDesc}
    , #{param.fileMgmtCd}
    , #{token.gv_cmpnyCd}
    , #{token.gv_userCd}
    , #{token.gv_userNm}
    , #{token.gv_userCd}
    , NOW()
    , #{token.gv_userCd}
    , NOW()
)
ON DUPLICATE KEY UPDATE
    INSPECT_ANSWER_TYPE = VALUES(INSPECT_ANSWER_TYPE)
    , ANSWER_DESC       = VALUES(ANSWER_DESC)
    , FILE_MGMT_CD      = VALUES(FILE_MGMT_CD)
    , PERFORM_CMPNY_CD  = VALUES(PERFORM_CMPNY_CD)
    , PERFORM_USER_CD   = VALUES(PERFORM_USER_CD)
    , PERFORM_USER_NM   = VALUES(PERFORM_USER_NM)
    , UPDATE_NO         = #{token.gv_userCd}
    , UPDATE_DATE       = NOW()
